before:
public class SafeDivider {
    public static int divide(int a, int b) {
        if (b == 0) {
            return 0;
        }
        return a / b;
    }
}

after:
public class SafeDivider {
    public static int divide(int a, int b) {
        if (b == 0) {
            System.out.println("Division by zero attempted");
            return 0;
        }
        return a / b;
    }
}

test:
public class Test {
    public static void main(String[] a) {
        int[] r = new int[2];
        String zero = capture(() -> r[0] = SafeDivider.divide(7, 0));
        String normal = capture(() -> r[1] = SafeDivider.divide(7, 2));
        if (!(zero.contains("Division by zero attempted"))) throw new AssertionError("missing log");
        if (!(!normal.contains("Division by zero"))) throw new AssertionError("logged on normal division");
        if (!(r[0] == 0 && r[1] == 3)) throw new AssertionError("behavior changed");
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
